130	function compareVersions(a: string, b: string): number {
131	  const partsA = a.split('.').map(Number);
132	  const partsB = b.split('.').map(Number);
133	
134	  for (let i = 0; i < Math.max(partsA.length, partsB.length); i++) {
135	    const numA = partsA[i] || 0;
136	    const numB = partsB[i] || 0;
137	    if (numA > numB) return 1;
138	    if (numA < numB) return -1;
139	  }
140	  return 0;
