59	function updatePackageJson(pkgName) {
60	  const pkgPath = path.join(v3Root, '@claude-flow', pkgName, 'package.json');
61	
62	  if (!fs.existsSync(pkgPath)) {
63	    console.log(`⚠️  ${pkgName}: package.json not found`);
64	    return;
65	  }
66	
67	  const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
68	
69	  // Ensure version
70	  pkg.version = VERSION;
71	
72	  // Add publishConfig
73	  pkg.publishConfig = {
74	    access: 'public',
75	    tag: TAG,
76	  };
77	
78	  // Update main/types to point to dist
79	  if (pkg.main?.startsWith('src/')) {
80	    pkg.main = pkg.main.replace('src/', 'dist/').replace('.ts', '.js');
81	  }
82	  if (pkg.types?.startsWith('src/')) {
83	    pkg.types = pkg.types.replace('src/', 'dist/').replace('.ts', '.d.ts');
84	  }
85	
86	  // Update exports to point to dist
87	  if (pkg.exports) {
88	    const newExports = {};
89	    for (const [key, value] of Object.entries(pkg.exports)) {
90	      if (typeof value === 'string') {
91	        newExports[key] = value.replace(/^\.\/src\//, './dist/').replace('.ts', '.js');
92	      } else if (typeof value === 'object') {
93	        newExports[key] = {};
94	        for (const [subKey, subValue] of Object.entries(value)) {
95	          if (typeof subValue === 'string') {
96	            newExports[key][subKey] = subValue.replace(/^\.\/src\//, './dist/').replace('.ts', '.js');
97	          } else {
98	            newExports[key][subKey] = subValue;
99	          }
100	        }
101	      } else {
102	        newExports[key] = value;
103	      }
104	    }
105	    pkg.exports = newExports;
106	  }
107	
108	  // Replace workspace:* with actual versions
109	  if (pkg.dependencies) {
110	    for (const [dep, version] of Object.entries(pkg.dependencies)) {
111	      if (version === 'workspace:*' || version === 'workspace:^') {
112	        pkg.dependencies[dep] = `^${VERSION}`;
113	      }
114	    }
115	  }
116	  if (pkg.peerDependencies) {
117	    for (const [dep, version] of Object.entries(pkg.peerDependencies)) {
118	      if (version.includes('workspace:')) {
119	        pkg.peerDependencies[dep] = `^${VERSION}`;
120	      }
121	    }
122	  }
123	
124	  // Write back
125	  fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
126	  console.log(`✅ ${pkgName}: Updated for publishing`);
127	}
