227	  static async detectFormat(filePath: string): Promise<'rvf' | 'json' | 'sqlite' | 'unknown'> {
228	    if (!existsSync(filePath)) return 'unknown';
229	    const fd = await import('node:fs').then(m => m.promises.open(filePath, 'r'));
230	    try {
231	      const buf = Buffer.alloc(16);
